command:
cat >> /work/tmp/probes.py <<'PY'
probe('alias_module_listing', "mod foo
alias quick := foo::build
", ['--list','--alias-style','separate'], {'foo.just':"build target='module':
  @echo {{target}}
"})
probe('alias_module_wrong_listing', "mod foo
alias quick := foo::build
build:
  @echo local
", ['--list','--alias-style','separate'], {'foo.just':"build target:
  @echo {{target}}
"})
d=BASE/'ceiling_relative'; (d/'sub').mkdir(parents=True,exist_ok=True); (d/'justfile').write_text('show:
  @echo PARENT
')
for ceiling in ['.',str(d/'sub')]:
    r=subprocess.run(['/target/debug/just','--ceiling',ceiling,'show'],cwd=d/'sub',capture_output=True,text=True,timeout=5)
    print(json.dumps(dict(name='ceiling_relative',ceiling=ceiling,code=r.returncode,stdout=r.stdout,stderr=r.stderr)))
probe('function_cached', "set unstable
x := uuid()
f() := x
show:
  @echo {{x}} {{f()}} {{f()}}
", ['show'])
PY
python3 /work/tmp/probes.py > /work/tmp/probes.log
tail -5 /work/tmp/probes.log
cd /work/crate && RUSTUP_AUTO_INSTALL=0 RUSTDOCFLAGS='-D warnings' cargo doc --locked --no-deps > /work/tmp/public-doc.log 2>&1; result=$?; tail -20 /work/tmp/public-doc.log; exit "$result"
